    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")
    if not giraffe_patches: return image_patch

    sunlight = [g for g in giraffe_patches if g.verify_property("giraffe", "direct sunlight")]
    shade = [g for g in giraffe_patches if g.verify_property("giraffe", "shade")]

    if sunlight and shade:
        sunlight_depth = sunlight[0].compute_depth()
        shade_depth = shade[0].compute_depth()
        if sunlight_depth < shade_depth:
            return sunlight[0]
        else:
            return shade[0]
    elif sunlight:
        return sunlight[0]
    elif shade:
        return shade[0]
    else:
        return giraffe_patches[0]

