        return image_patch
    moose_pajamas_patches = image_patch.find("moose pajamas")
    if not moose_pajamas_patches:
        return boy_patches[0]
    boy_depth = boy_patches[0].compute_depth()
    matching_boy = None
    min_depth_diff = float('inf')
    for boy in boy_patches:
        if boy.overlaps_with(0, 0, 100, 100) and moose_pajamas_patches[0].overlaps_with(0, 0, 100, 100):
            depth_diff = abs(boy.compute_depth() - moose_pajamas_patches[0].compute_depth())
            if depth_diff < min_depth_diff:
                min_depth_diff = depth_diff
                matching_boy = boy
    return matching_boy if matching_boy else boy_patches[0]

