def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    skateboard_patches = image_patch.find("skateboard")
    mattress_patches = image_patch.find("mattress")

    if not man_patches or not skateboard_patches or not mattress_patches:
        return image_patch

    for man in man_patches:
        for skateboard in skateboard_patches:
            for mattress in mattress_patches:
                if man.overlaps_with(skateboard.left, skateboard.lower, skateboard.right, skateboard.upper) and \
                   man.overlaps_with(mattress.left, mattress.lower, mattress.right, mattress.upper):
                    return man

    return man_patches[0]

